    this.route.params.pipe(switchMap(params => {
      this.routeChanged$.next();
      this.tsm.disconnect();
      this.tsm.resetFilters();
      this.displayOptions = GroupMonitorComponent.defaultDisplayOptions();
      this.currentlySelected = null;
