  private readonly nativeText = new CustomtextPipe(inject(CustomtextService));
  readonly customtext = this.nativeText.transform.bind(this.nativeText);
  readonly timeLeftView = new TimeLeftPipe().transform;
  readonly position = new PositionPipe().transform;
  readonly isCodeClear = new IsCodeClearPipe().transform;
  readonly testletVisible = new TestletvisiblePipe().transform;

  private readonly locale=inject(LOCALE_ID);
  formatRemainingTime(value:number):string{return formatNativeMonitorMinutes(value,this.locale);}
  @Input() testSession!: TestSession;
  @Input() displayOptions!: TestViewDisplayOptions;
  @Input() marked: Selected | null = null;
  @Input() selected: Selected | null = null;
  @Input() checked: boolean = false;
  @Input() bookletStates: { [p: string]: string } = {};

  @Output() markedElement$ = new EventEmitter<Selected>();
  @Output() selectedElement$ = new EventEmitter<Selected>();
  @Output() checked$ = new EventEmitter<boolean>();

  superStateIcons: Partial<Record<TestSessionSuperState, IconData>> = superStates;

  // TODO use pipes for the following functions
  stateString = TestSessionUtil.stateString;
  bookletStateLabel = TestSessionUtil.bookletStateLabel;
  hasState = TestSessionUtil.hasState;
  isBooklet = isBooklet;
  isTestlet = isTestlet;
  // eslint-disable-next-line class-methods-use-this
  trackUnits = (index: number, testlet: Testlet | UnitDef): string => testlet.id || index.toString();

  testletContext?: TestletContext;

  mark(testletOrNull: Testlet | null = null): void {
    if ((testletOrNull != null) && !testletOrNull.blockId) {
      return;
    }
    if (['pending', 'locked'].includes(this.testSession.state)) {
      return;
    }
    this.marked = this.returnAsSelected(testletOrNull);
    this.markedElement$.emit(this.marked);
  }

  isSelectionTheSameBlockAsParentSelection(testletOrNull: Testlet | null = null): boolean {
    return !!testletOrNull && //  is something Nowselected?
      (this.selected?.element?.blockId === testletOrNull?.blockId) && // is nowselected already in parentselection?
      // is nowselected same species as parentselection (is it the same block 1? == same col)
      (this.selected?.originSession.booklet.species === this.testSession.booklet.species);
  }

  returnClicks(testletOrNull: Testlet | null = null): 'first' | 'second' | 'third' {
    const isSelectionInSameSession = this.isSelectionTheSameBlockAsParentSelection(testletOrNull) &&
      // is the nowSelection the same Session (row in Table)
      (this.selected?.originSession.data.testId === this.testSession.data.testId);

    if (isSelectionInSameSession && this.selected?.nthClick === 'first') {
      return 'second';
    }
    if (isSelectionInSameSession && this.selected?.nthClick === 'second') {
      return 'third';
    }
    return 'first';
  }

  isMarked(testletOrNull: Testlet | null = null): boolean {
    return !!testletOrNull &&
      (!['pending', 'locked'].includes(this.testSession.state)) &&
      (this.marked?.element?.blockId === testletOrNull.blockId) &&
      (this.marked?.originSession.booklet.species === this.testSession.booklet.species);
  }

  select(testletOrNull: Testlet | null): void {
    if ((testletOrNull != null) && !testletOrNull.blockId) {
      return;
    }
    this.applySelection(testletOrNull);
  }

  deselect($event: MouseEvent | null): void {
    if ($event && ($event.currentTarget === $event.target)) {
      this.applySelection();
    }
  }

  deselectForce($event: Event): boolean {
    this.applySelection();
    $event.stopImmediatePropagation();
    $event.stopPropagation();
    $event.preventDefault();
    return false;
  }

  invertSelection(): boolean {
    this.applySelection(this.selected?.element, true);
    return false;
  }

  toggleCheckbox($event: MatCheckboxChange): void {
    this.checked$.emit($event.checked);
  }

  private applySelection(testletOrNull: Testlet | null = null, inversion = false): void {
    if (['pending', 'locked'].includes(this.testSession.state)) {
      return;
    }
    this.selected = this.returnAsSelected(testletOrNull, inversion);
    this.selectedElement$.emit(this.selected);
  }

  private returnAsSelected(testletOrNull: Testlet | null = null, inversion = false): Selected {
    return {
      element: testletOrNull,
      originSession: this.testSession,
      nthClick: this.returnClicks(testletOrNull),
      inversion
    };
  }
}
import type { TestSessionChange } from '../../common/test-session-change.interface';
import {
  type Booklet,
  type BookletError, isBooklet,
  isUnit,
  type Testlet,
  type TestSession,
  type TestSessionData,
  type TestSessionSuperState,
  type UnitContext
} from '../group-monitor.interfaces';

export class TestSessionUtil {
  static bookletStateLabel(session: TestSession, stateId: string): string | undefined {
    const state = isBooklet(session.booklet) ? session.booklet.states[stateId] : undefined;
    const option = session.bookletStates?.[stateId] || state?.default;
    return option ? state?.options[option]?.label : undefined;
  }

  static hasState(state: Record<string, unknown>, key: string, value: string | null = null): boolean {
    return ((typeof state[key] !== 'undefined') && ((value !== null) ? (state[key] === value) : true));
  }

  static isPaused(session: TestSession): boolean {
    return TestSessionUtil.hasState(session.data.testState, 'CONTROLLER', 'PAUSED');
  }

  static isLocked(session: TestSession): boolean {
    return TestSessionUtil.hasState(session.data.testState, 'status', 'locked');
  }

  static analyzeTestSession(session: TestSessionChange, booklet: Booklet | BookletError): TestSession {
    const current = (isBooklet(booklet) && session.unitName) ?
      TestSessionUtil.getCurrent(booklet.units, session.unitName) :
      null;
    return {
      data: session,
      state: TestSessionUtil.getSuperState(session),
      current: current && current.unit ? current : null,
      booklet,
      timeLeft: TestSessionUtil.parseJsonState<{ [timerId: string]: number }>(session.testState, 'TESTLETS_TIMELEFT'),
      clearedCodes: TestSessionUtil.parseJsonState<string[]>(session.testState, 'TESTLETS_CLEARED_CODE'),
      bookletStates: TestSessionUtil.parseJsonState<{ [state: string]: string }>(session.testState, 'BOOKLET_STATES')
    };
  }

  static stateString(state: Record<string, string>, keys: string[], glue = ''): string {
    return keys
      .map((key: string) => (TestSessionUtil.hasState(state, key) ? state[key] : null))
      .filter(value => value !== null)
      .join(glue);
  }

  private static getSuperState(session: TestSessionData): TestSessionSuperState {
    const state = session.testState;

    if (this.hasState(state, 'status', 'pending')) {
      return 'pending';
    }
    if (this.hasState(state, 'status', 'locked')) {
      return 'locked';
    }
    if (this.hasState(state, 'CONTROLLER', 'ERROR')) {
      return 'error';
    }
    if (this.hasState(state, 'CONTROLLER', 'TERMINATED')) {
      return 'controller_terminated';
    }
    if (this.hasState(state, 'CONTROLLER', 'TERMINATED_PAUSED')) {
      return 'controller_terminated';
    }
    if (this.hasState(state, 'CONNECTION', 'LOST')) {
      return 'connection_lost';
    }
    if (this.hasState(state, 'CONTROLLER', 'PAUSED')) {
      return 'paused';
    }
    if (this.hasState(state, 'FOCUS', 'HAS_NOT')) {
      return 'focus_lost';
    }
    if (TestSessionUtil.idleSinceMinutes(session) > 5) {
      return 'idle';
    }
    if (this.hasState(state, 'CONNECTION', 'WEBSOCKET')) {
      return 'connection_websocket';
    }
    if (this.hasState(state, 'CONNECTION', 'POLLING')) {
      return 'connection_polling';
    }
    return 'ok';
  }

  private static idleSinceMinutes(testSession: TestSessionData): number {
    return (Date.now() - testSession.timestamp * 1000) / (1000 * 60);
  }

  private static parseJsonState<T>(testStateObject: Record<string, string>, key: string): T | null {
    if (typeof testStateObject[key] === 'undefined') {
      return null;
    }

    const stateValueString = testStateObject[key];

    try {
      return JSON.parse(stateValueString);
    } catch (error) {
      return null;
    }
  }

  private static getCurrent(
    testlet: Testlet,
    searchUnitId: string,
    level = 0,
    context: UnitContext | null = null
  ): UnitContext {
    const result: UnitContext = context ?? {
      unit: undefined,
      parent: testlet,
      ancestor: testlet,
      indexGlobal: -1,
      indexLocal: -1,
      indexAncestor: -1
    };

    for (let i = 0; i < testlet.children.length; i++) {
      const child = testlet.children[i];
      if (isUnit(child)) {
        result.indexLocal += 1;
        result.indexAncestor += 1;
        result.indexGlobal += 1;

        if (child.alias === searchUnitId) {
          result.unit = child;
          return result;
        }
      } else {
        const subResult = TestSessionUtil.getCurrent(child, searchUnitId, level + 1, {
          unit: undefined,
          parent: child,
          ancestor: level < 1 ? child : result.ancestor,
          indexGlobal: result.indexGlobal,
          indexLocal: -1,
          indexAncestor: level < 1 ? -1 : result.indexAncestor
        });
        if (subResult.unit) {
          return subResult;
        }
        result.indexGlobal = subResult.indexGlobal;
        result.indexAncestor = level < 1 ? result.indexAncestor : subResult.indexAncestor;
      }
    }

    return result;
  }
}
