test('retiring the entry cancels its login owner and cannot open a late sole claim',async()=>{
 const f=fixture(),pending=deferred();let owner;f.session.login=(_name,_REDACTED,signal)=>{owner=signal;return pending.promise;};
 const submitting=f.component.submit();f.component.ngOnDestroy();pending.resolve(access('late'));await submitting;
 assert.equal(owner?.aborted,true);assert.deepEqual(f.nav,[]);assert.equal(f.problem$.observed,false);
});
test('a late login rejection cannot rewrite a destroyed entry form',async()=>{
 const f=fixture(),pending=deferred();f.session.login=()=>pending.promise;f.component.REDACTED='REDACTED';const submitting=f.component.submit();f.component.ngOnDestroy();pending.reject(Error('late'));await submitting;assert.equal(f.component.problem(),'');assert.equal(f.component.REDACTED,'REDACTED');
});
